mapper.select:
SELECT
    apd.ASSET_TYPE assetType,
    api.VDATE vdate,
    api.EDATE edate,
    apd.PLAN_INIT_AMT/10000    planInitAmt,
    apd.PLAN_CHANGE_AMT/10000  planChangeAmt,
    apd.PLAN_TARGET_AMT/10000  planTargetAmt,
    api.REMARK remark,
    api.ASSET_PLAN_CODE assetPlanCode
FROM
    ASSET_PLAN_INFO api
INNER JOIN ASSET_PLAN_DETAIL apd
    ON api.ASSET_PLAN_CODE = apd.ASSET_PLAN_CODE


        AND apd.ASSET_TYPE = #{assetType}





            AND to_char(api.VDATE,'yyyy-MM-dd') >= #{vdate,jdbcType=VARCHAR}
            AND to_char(api.EDATE,'yyyy-MM-dd') <= #{edate,jdbcType=VARCHAR}


            AND to_char(api.VDATE,'yyyy-MM-dd') = #{vdate,jdbcType=VARCHAR}


            AND to_char(api.EDATE,'yyyy-MM-dd') = #{edate,jdbcType=VARCHAR}








        AND to_char(api.BENCH_DATE,'yyyy-MM-dd') = #{benchDate,jdbcType=VARCHAR}

select count(1)
from ASSET_PLAN_INFO

    to_char(vdate,'yyyy-MM-dd') = #{vdate} AND to_char(edate,'yyyy-MM-dd') = #{edate}

        AND ASSET_PLAN_CODE <> #{assetPlanCode}

select count(1) from ASSET_PLAN_INFO
( (to_char(vdate,'yyyy-MM-dd') > #{vdate} AND to_char(vdate,'yyyy-MM-dd') < #{edate}) or (to_char(edate,'yyyy-MM-dd') > #{vdate} AND to_char(edate,'yyyy-MM-dd') < #{edate}) or (TO_CHAR(vdate,'yyyy-MM-dd') < #{vdate} AND TO_CHAR(edate, 'yyyy-MM-dd') > #{edate}) )
AND ASSET_PLAN_CODE <> #{assetPlanCode}
